    "tt.tabs.spiritual": "\u0c06\u0c27\u0c4d\u0c2f\u0c3e\u0c24\u0c4d\u0c2e\u0c3f\u0c15\u0c02",
    "tt.tabs.alone": "\u0c12\u0c02\u0c1f\u0c30\u0c3f\u0c17\u0c3e",
